```python
import json, hashlib, hmac, base64, time, re
from urllib.parse import urlparse, parse_qs

def base64url_encode(data):
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode()

def create_jwt(payload, secret):
    header = base64url_encode(json.dumps({'alg': 'HS256', 'typ': 'JWT'}).encode())
    payload_enc = base64url_encode(json.dumps(payload).encode())
    sig = hmac.new(secret.encode(), f'{header}.{payload_enc}'.encode(), hashlib.sha256).digest()
    return f'{header}.{payload_enc}.{base64url_encode(sig)}'

class Router:
    def __init__(self):
        self.routes = []
    def route(self, path, methods=['GET']):
        def wrapper(func):
            self.routes.append({'path': path, 'methods': methods, 'handler': func})
            return func
        return wrapper
    def dispatch(self, request):
        for route in self.routes:
            if self._match(request.path, route['path']):
                return route['handler'](request)
        return {'status': 404, 'body': 'Not found'}
    def _match(self, request_path, route_path):
        parts_a = request_path.strip('/').split('/')
        parts_b = route_path.strip('/').split('/')
        if len(parts_a) != len(parts_b):
            return False
        for a, b in zip(parts_a, parts_b):
            if b.startswith(':'): continue
            if a != b: return False
        return True
